385	async function collectLiveRows(options = {}) {
386	  const logger = typeof options?.warn === "function" ? options : options.logger || defaultRelayLogger;
387	  const pool = typeof options?.warn === "function" ? null : options.pool || null;
388	  const excludedURLs = new Set((typeof options?.warn === "function" ? [] : options.excludeURLs || [])
389	    .map(canonicalURLString));
390	  const endpoints = discoverLoopbackEndpoints()
391	    .filter((endpoint) => !excludedURLs.has(canonicalURLString(endpoint.url)));
392	  const maxConcurrent = pool?.labelLimit?.("live-status") || endpoints.length || 1;
393	  const results = await allSettledInBatches(
394	    endpoints,
395	    maxConcurrent,
396	    (endpoint) => readLoadedRows(endpoint, {
397	      logger,
398	      pool,
399	      timeoutMs: LIVE_STATUS_UPSTREAM_TIMEOUT_MS,
400	    }),
401	  );
402	  const rowsById = new Map();
403	  let failedEndpoints = 0;
404	  for (let index = 0; index < results.length; index += 1) {
405	    const result = results[index];
406	    if (result.status === "rejected") {
407	      failedEndpoints += 1;
408	      logger.warn("live.endpoint_query_failed", {
409	        endpointUrl: endpoints[index].url,
410	        error: result.reason,
411	      });
412	      continue;
413	    }
414	    for (const row of result.value) {
415	      rowsById.set(row.id, preferThread(row, rowsById.get(row.id)));
416	    }
417	  }
418	  return {
419	    endpoints,
420	    failedEndpoints,
421	    rows: [...rowsById.values()],
422	  };
423	}
