  7	function liveOverlayForSnapshot(snapshot, maxAgeMs = LIVE_STATUS_MAX_AGE_MS) {
  8	  const ageMs = snapshot.checkedAtMs ? Date.now() - snapshot.checkedAtMs : null;
  9	  if (snapshot.ok && ageMs !== null && ageMs <= maxAgeMs) {
 10	    if (snapshot.failedEndpoints > 0) {
 11	      return {
 12	        ok: false,
 13	        state: "degraded",
 14	        ageMs,
 15	        endpoints: snapshot.endpoints.length,
 16	        failedEndpoints: snapshot.failedEndpoints,
 17	        rows: snapshot.rows.length,
 18	      };
 19	    }
 20	    return {
 21	      ok: true,
 22	      state: "ready",
 23	      ageMs,
 24	      endpoints: snapshot.endpoints.length,
 25	      failedEndpoints: snapshot.failedEndpoints,
 26	      rows: snapshot.rows.length,
 27	    };
 28	  }
 29	  if (snapshot.ok && ageMs !== null) {
 30	    return {
 31	      ok: false,
 32	      state: "stale",
 33	      ageMs,
 34	    };
 35	  }
 36	  return {
 37	    ok: false,
 38	    state: snapshot.checkedAtMs ? "unavailable" : "disabled",
 39	    ageMs,
 40	  };
 41	}
