 43	class LiveStatusCache {
 44	  constructor({
 45	    collectLiveRows,
 46	    logger = defaultRelayLogger,
 47	    statusTracker = null,
 48	    refreshIntervalMs = LIVE_STATUS_REFRESH_INTERVAL_MS,
 49	    maxAgeMs = LIVE_STATUS_MAX_AGE_MS,
 50	  }) {
 51	    this.collectLiveRows = collectLiveRows;
 52	    this.logger = logger;
 53	    this.statusTracker = statusTracker;
 54	    this.refreshIntervalMs = refreshIntervalMs;
 55	    this.maxAgeMs = maxAgeMs;
 56	    this.refreshTimer = null;
 57	    this.refreshPromise = null;
 58	    this.state = {
 59	      checkedAt: null,
 60	      checkedAtMs: null,
 61	      ok: false,
 62	      status: "unknown",
 63	      endpoints: [],
 64	      failedEndpoints: 0,
 65	      rows: [],
 66	      error: null,
 67	    };
 68	  }
 69	
 70	  start() {
 71	    if (this.refreshTimer || !this.collectLiveRows) {
 72	      return;
 73	    }
 74	    this.refreshTimer = setInterval(() => {
 75	      this.refreshNow().catch((error) => {
 76	        this.logger.warn("live_status.refresh_failed", { error });
 77	      });
 78	    }, this.refreshIntervalMs);
 79	    this.refreshTimer.unref?.();
 80	  }
 81	
 82	  stop() {
 83	    if (this.refreshTimer) {
 84	      clearInterval(this.refreshTimer);
 85	      this.refreshTimer = null;
 86	    }
 87	  }
 88	
 89	  async refreshNow() {
 90	    if (!this.collectLiveRows) {
 91	      return this.snapshot();
 92	    }
 93	    if (this.refreshPromise) {
 94	      return this.refreshPromise;
 95	    }
 96	    this.refreshPromise = (async () => {
 97	      try {
 98	        const live = await this.collectLiveRows(this.logger);
 99	        this.state = {
100	          checkedAt: new Date().toISOString(),
101	          checkedAtMs: Date.now(),
102	          ok: true,
103	          status: "up",
104	          endpoints: live.endpoints || [],
105	          failedEndpoints: live.failedEndpoints || 0,
106	          rows: live.rows || [],
107	          error: null,
108	        };
109	        this.statusTracker?.recordLiveDiscovery({
110	          status: "up",
111	          ok: true,
112	          endpoints: this.state.endpoints.length,
113	          failedEndpoints: this.state.failedEndpoints,
114	          rows: this.state.rows.length,
115	        });
116	        return this.snapshot();
117	      } catch (error) {
118	        this.state = {
119	          checkedAt: new Date().toISOString(),
120	          checkedAtMs: Date.now(),
121	          ok: false,
122	          status: "down",
123	          endpoints: [],
124	          failedEndpoints: 1,
125	          rows: [],
126	          error,
127	        };
128	        this.statusTracker?.recordLiveDiscovery({
129	          status: "down",
130	          ok: false,
131	          error,
132	        });
133	        return this.snapshot();
134	      } finally {
135	        this.refreshPromise = null;
136	      }
137	    })();
138	    return this.refreshPromise;
139	  }
140	
141	  async snapshotForRouting() {
142	    const snapshot = this.snapshot();
143	    const ageMs = snapshot.checkedAtMs ? Date.now() - snapshot.checkedAtMs : null;
144	    if (ageMs === null || ageMs > this.maxAgeMs) {
145	      return this.refreshNow();
146	    }
147	    return snapshot;
148	  }
149	
150	  snapshot() {
151	    return {
152	      ...this.state,
153	      rows: [...this.state.rows],
154	      endpoints: [...this.state.endpoints],
155	      liveOverlay: liveOverlayForSnapshot(this.state, this.maxAgeMs),
156	    };
157	  }
158	
159	  liveOverlay() {
160	    return this.snapshot().liveOverlay;
161	  }
162	}
