 95	  }
 96	  if (status?.type === "idle") {
 97	    return 2;
 98	  }
 99	  if (status?.type === "systemError") {
100	    return 3;
101	  }
102	  if (status?.type === "notLoaded") {
103	    return 5;
104	  }
