161	  const existingPriority = statusPriority(existing);
162	  if (candidatePriority !== existingPriority) {
163	    return candidatePriority < existingPriority ? candidate : existing;
164	  }
165	  return rowTimestamp(candidate) >= rowTimestamp(existing) ? candidate : existing;
