921	    private func shouldPrefer(_ candidate: SessionSummary, over existing: SessionSummary) -> Bool {
922	        if existing.origin.kind == .humanInteractive,
923	           candidate.origin.kind != .humanInteractive {
924	            return true
925	        }
926	        if existing.origin.kind == .unknown,
927	           candidate.origin.kind == .agentOrAutomation {
928	            return true
929	        }
930	        return false
931	    }
