 73	    private func relativeTime(since date: Date) -> String {
 74	        let seconds = max(0, Int(now().timeIntervalSince(date)))
 75	
 76	        switch seconds {
 77	        case 0..<60:
 78	            return "now"
 79	        case 60..<3_600:
