  4	    let lens: DockLensID
  5	    let searchText: String
  6	    let filters: DockFilterState
  7	
  8	    init(
  9	        lens: DockLensID = .newest,
 10	        searchText: String = "",
 11	        filters: DockFilterState = .default
 12	    ) {
 13	        self.lens = lens
 14	        self.searchText = searchText
 15	        self.filters = filters
