 19	struct DockSessionProjection: Equatable, Sendable {
 20	    let lens: DockLensID
 21	    let rows: [DockRowViewModel]
 22	    let groups: [DockProjectionGroupViewModel]
 23	    let summary: DockProjectionSummary
 24	    let hiddenCounts: DockProjectionHiddenCounts
 25	    let availableFacets: DockProjectionFacets
 26	    let emptyReason: DockProjectionEmptyReason?
 27	    let isPartial: Bool
 28	    let checkingHostCount: Int
 29	}
