 31	extension DockSnapshot {
 32	    func project(options: DockProjectionOptions) -> DockSessionProjection {
 33	        DockSessionProjectionProjector(snapshot: self, options: options).project()
 34	    }
 35	}
 36	
 37	private struct DockSessionProjectionProjector {
 38	    let snapshot: DockSnapshot
 39	    let options: DockProjectionOptions
 40	
 41	    func project() -> DockSessionProjection {
 42	        let searchedRows = snapshot.rows.filter(matchesSearch)
 43	        let filteredIgnoringIdle = searchedRows.filter(matchesNonIdleFilters)
 44	        let hiddenIdleRows = options.filters.showsIdle
 45	            ? []
 46	            : filteredIgnoringIdle.filter { $0.status == .idle }
 47	        let hiddenIdleCount = hiddenIdleRows.count
 48	        let visibleRows = filteredIgnoringIdle
 49	            .filter { options.filters.showsIdle || $0.status != .idle }
 50	            .sorted(by: rowPrecedesByRecency)
 51	        let groups = groups(for: visibleRows, hiddenIdleRows: hiddenIdleRows)
 52	        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows, hiddenIdleCount: hiddenIdleCount) : nil
 53	
 54	        return DockSessionProjection(
 55	            lens: options.lens,
 56	            rows: options.lens == .newest ? visibleRows : [],
 57	            groups: groups,
 58	            summary: summary(for: visibleRows),
 59	            hiddenCounts: DockProjectionHiddenCounts(idle: hiddenIdleCount),
 60	            availableFacets: availableFacets(),
 61	            emptyReason: emptyReason,
 62	            isPartial: snapshot.isPartial,
 63	            checkingHostCount: snapshot.hostStates.filter { $0.status == .checking }.count
 64	        )
 65	    }
 66	
 67	    private func groups(
 68	        for rows: [DockRowViewModel],
 69	        hiddenIdleRows: [DockRowViewModel]
 70	    ) -> [DockProjectionGroupViewModel] {
 71	        switch options.lens {
 72	        case .newest:
 73	            return []
 74	        case .host:
 75	            return hostGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
 76	        case .branch:
 77	            return branchGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
 78	        }
 79	    }
 80	
 81	    private func hostGroups(
 82	        for rows: [DockRowViewModel],
 83	        hiddenIdleRows: [DockRowViewModel]
 84	    ) -> [DockProjectionGroupViewModel] {
 85	        let rowsByHost = Dictionary(grouping: rows, by: \.id.hostID)
 86	        let hiddenIdleRowsByHost = Dictionary(grouping: hiddenIdleRows, by: \.id.hostID)
 87	        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
 88	        return snapshot.hosts.compactMap { host in
 89	            if !options.filters.selectedHostIDs.isEmpty,
 90	               !options.filters.selectedHostIDs.contains(host.id) {
 91	                return nil
 92	            }
 93	
 94	            let hostRows = (rowsByHost[host.id] ?? []).sorted(by: rowPrecedesByRecency)
 95	            let hiddenIdleCount = hiddenIdleRowsByHost[host.id]?.count ?? 0
 96	            let hostState = stateByHost[host.id]
 97	            let isUnavailable = hostState?.status.isUnavailable ?? false
 98	            guard !hostRows.isEmpty || hiddenIdleCount > 0 || isUnavailable || hostState?.status == .checking else {
 99	                return nil
100	            }
101	
102	            return DockProjectionGroupViewModel(
103	                id: "host::\(host.id)",
104	                kind: .host,
105	                title: host.displayName,
106	                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
107	                rows: hostRows,
108	                hostIDs: [host.id],
109	                newestActivityDate: hostRows.map(\.lastActivityDate).max(),
110	                runningCount: hostRows.filter { $0.status == .running }.count,
111	                hiddenIdleCount: hiddenIdleCount,
112	                isUnavailable: isUnavailable,
113	                unavailableMessage: hostState?.status.unavailableMessage
114	            )
115	        }
116	        .sorted(by: groupPrecedes)
117	    }
118	
119	    private func branchGroups(
120	        for rows: [DockRowViewModel],
121	        hiddenIdleRows: [DockRowViewModel]
122	    ) -> [DockProjectionGroupViewModel] {
123	        let groupedRows = Dictionary(grouping: rows, by: \.branch)
124	        let hiddenIdleCountsByBranch = Dictionary(grouping: hiddenIdleRows, by: \.branch)
125	            .mapValues(\.count)
126	        return groupedRows.map { branch, rows in
127	            let sortedRows = rows.sorted(by: rowPrecedesByRecency)
128	            let hostNames = Set(sortedRows.map(\.hostDisplayName)).sorted()
129	            return DockProjectionGroupViewModel(
130	                id: "branch::\(branch)",
131	                kind: .branch,
132	                title: branch,
133	                subtitle: "\(sortedRows.count) sessions · \(hostNames.joined(separator: ", "))",
134	                rows: sortedRows,
135	                hostIDs: Set(sortedRows.map(\.id.hostID)).sorted(),
136	                newestActivityDate: sortedRows.map(\.lastActivityDate).max(),
137	                runningCount: sortedRows.filter { $0.status == .running }.count,
138	                hiddenIdleCount: hiddenIdleCountsByBranch[branch] ?? 0,
139	                isUnavailable: false,
140	                unavailableMessage: nil
141	            )
142	        }
143	        .sorted(by: groupPrecedes)
144	    }
145	
146	    private func summary(for rows: [DockRowViewModel]) -> DockProjectionSummary {
147	        var parts: [String] = ["\(rows.count.formatted()) shown"]
148	        parts.append(hostSummaryText)
149	        parts.append(branchSummaryText)
150	        parts.append(statusSummaryText)
151	        parts.append(repositorySummaryText)
152	        parts.append("Source: \(options.filters.source.label)")
153	        parts.append(options.filters.showsIdle ? "Idle shown" : "Idle hidden")
154	
155	        let query = normalizedQuery(options.searchText)
156	        if !query.isEmpty {
157	            parts.append("Search: \(query)")
158	        }
159	        if snapshot.isPartial {
160	            parts.append("Partial")
161	        }
162	
163	        return DockProjectionSummary(
164	            text: parts.joined(separator: " · "),
165	            activeFilterCount: options.filters.activeFilterCount + (query.isEmpty ? 0 : 1),
166	            resultCount: rows.count
167	        )
168	    }
169	
170	    private var hostSummaryText: String {
171	        guard !options.filters.selectedHostIDs.isEmpty else {
172	            return "Hosts: Any"
173	        }
174	        if options.filters.selectedHostIDs.count == 1,
175	           let hostID = options.filters.selectedHostIDs.first {
176	            return "Host: \(hostName(for: hostID))"
177	        }
178	        return "Hosts: \(options.filters.selectedHostIDs.count)"
179	    }
180	
181	    private var branchSummaryText: String {
182	        guard !options.filters.selectedBranches.isEmpty else {
183	            return "Branches: Any"
184	        }
185	        if options.filters.selectedBranches.count == 1,
186	           let branch = options.filters.selectedBranches.first {
187	            return "Branch: \(branch)"
188	        }
189	        return "Branches: \(options.filters.selectedBranches.count)"
190	    }
191	
192	    private var statusSummaryText: String {
193	        let allStatuses = Set(DockRowStatusKind.allCases)
194	        guard options.filters.statusKinds != allStatuses else {
195	            return "Status: Any"
196	        }
197	        if options.filters.statusKinds.count == 1,
198	           let status = options.filters.statusKinds.first {
199	            return "Status: \(status.label)"
200	        }
201	        return "Statuses: \(options.filters.statusKinds.count)"
202	    }
203	
204	    private var repositorySummaryText: String {
205	        let query = normalizedQuery(options.filters.repositoryQuery)
206	        let selectedCount = options.filters.selectedRepositories.count
207	        if selectedCount == 0, query.isEmpty {
208	            return "Repo: Any"
209	        }
210	        if selectedCount == 1,
211	           query.isEmpty,
212	           let repository = options.filters.selectedRepositories.first {
213	            return "Repo: \(repository)"
214	        }
215	        if selectedCount == 0 {
216	            return "Repo search: \(query)"
217	        }
218	        if query.isEmpty {
219	            return "Repos: \(selectedCount)"
220	        }
221	        return "Repos: \(selectedCount), search: \(query)"
222	    }
223	
224	    private func availableFacets() -> DockProjectionFacets {
225	        DockProjectionFacets(
226	            hosts: snapshot.hosts,
227	            branches: uniqueSorted(snapshot.rows.map(\.branch)),
228	            statuses: DockRowStatusKind.allCases.filter { status in
229	                snapshot.rows.contains { $0.status == status }
230	            },
231	            repositories: uniqueSorted(snapshot.rows.map(\.repository)),
232	            sources: DockSourceFilter.allCases.filter { source in
233	                source == .any || snapshot.rows.contains { source.includes($0.origin) }
234	            }
235	        )
236	    }
237	
238	    private func hostName(for hostID: String) -> String {
239	        snapshot.hosts.first { $0.id == hostID }?.displayName ?? hostID
240	    }
241	
242	    private func emptyReason(
243	        searchedRows: [DockRowViewModel],
244	        hiddenIdleCount: Int
245	    ) -> DockProjectionEmptyReason {
246	        if snapshot.rows.isEmpty {
247	            return .noData
248	        }
249	        if hiddenIdleCount > 0 {
250	            return .idleHidden
251	        }
252	        if !normalizedQuery(options.searchText).isEmpty, searchedRows.isEmpty {
253	            return .noSearchMatches
254	        }
255	        if options.filters.statusKinds == [.notLoaded] {
256	            return .notLoadedOnly
257	        }
258	        if selectedHostsAreUnavailable {
259	            return .hostUnavailable
260	        }
261	        return .noFilterMatches
262	    }
263	
264	    private var selectedHostsAreUnavailable: Bool {
265	        guard !options.filters.selectedHostIDs.isEmpty else {
266	            return false
267	        }
268	        let states = snapshot.hostStates.filter { options.filters.selectedHostIDs.contains($0.host.id) }
269	        return !states.isEmpty && states.allSatisfy(\.status.isUnavailable)
270	    }
271	
272	    private func matchesNonIdleFilters(_ row: DockRowViewModel) -> Bool {
273	        if !options.filters.selectedHostIDs.isEmpty,
274	           !options.filters.selectedHostIDs.contains(row.id.hostID) {
275	            return false
276	        }
277	        if !options.filters.selectedBranches.isEmpty,
278	           !options.filters.selectedBranches.contains(where: { selected in
279	               row.branch.compare(selected, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
280	           }) {
281	            return false
282	        }
283	        if !options.filters.statusKinds.contains(row.status) {
284	            return false
285	        }
286	        if !options.filters.selectedRepositories.isEmpty,
287	           !options.filters.selectedRepositories.contains(row.repository) {
288	            return false
289	        }
290	        let repositoryQuery = normalizedQuery(options.filters.repositoryQuery)
291	        if !repositoryQuery.isEmpty,
292	           !row.repository.localizedCaseInsensitiveContains(repositoryQuery) {
293	            return false
294	        }
295	        return options.filters.source.includes(row.origin)
296	    }
297	
298	    private func matchesSearch(_ row: DockRowViewModel) -> Bool {
299	        let query = normalizedQuery(options.searchText)
300	        guard !query.isEmpty else {
301	            return true
302	        }
303	
304	        return searchableValues(for: row).contains { value in
305	            value.localizedCaseInsensitiveContains(query)
306	        }
307	    }
308	
309	    private func searchableValues(for row: DockRowViewModel) -> [String] {
310	        [
311	            row.title,
312	            row.hostDisplayName,
313	            row.id.hostID,
314	            row.repository,
315	            row.branch,
316	            row.summary,
317	            row.status.label,
318	            row.label,
319	            row.origin.automationKind,
320	            row.id.threadID

