  3	public struct DockRelayEndpoint: Codable, Equatable, Sendable, Identifiable {
  4	    public let host: String
  5	    public let port: Int
  6	
  7	    public var id: String { serializedEndpoint }
  8	
  9	    public var serializedEndpoint: String {
 10	        "\(serializedHost):\(port)"
 11	    }
 12	
 13	    public var displayEndpoint: String {
 14	        serializedEndpoint
 15	    }
 16	
 17	    public var webSocketURL: URL {
 18	        // URL is transport-only. App config and persistence stay host+port.
 19	        URL(string: "ws://\(serializedEndpoint)")!
 20	    }
 21	
 22	    public var statusURL: URL {
 23	        URL(string: "http://\(serializedEndpoint)/statusz")!
 24	    }
 25	
 26	    private var serializedHost: String {
 27	        host.contains(":") ? "[\(host)]" : host
 28	    }
 29	
 30	    public init(host rawHost: String, port: Int) throws {
 31	        let host = try Self.normalizedHost(rawHost)
 32	        guard (1...CodexDockConstants.Ports.maximumTCPPort).contains(port) else {
 33	            throw DockHostConfigurationError.invalidPort(String(port))
 34	        }
 35	        self.host = host
 36	        self.port = port
 37	    }
 38	
 39	    public static func parse(_ rawValue: String) throws -> DockRelayEndpoint {
 40	        let value = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
 41	        guard !value.isEmpty else {
 42	            throw DockHostConfigurationError.missingEndpoint
 43	        }
 44	
 45	        let host: String
 46	        let portText: String
 47	        if value.hasPrefix("[") {
 48	            guard let closeIndex = value.firstIndex(of: "]") else {
 49	                throw DockHostConfigurationError.invalidEndpoint(value)
 50	            }
 51	            let afterClose = value.index(after: closeIndex)
 52	            guard afterClose < value.endIndex, value[afterClose] == ":" else {
 53	                throw DockHostConfigurationError.invalidEndpoint(value)
 54	            }
 55	            host = String(value[value.index(after: value.startIndex)..<closeIndex])
 56	            portText = String(value[value.index(after: afterClose)...])
 57	        } else {
 58	            let parts = value.split(separator: ":", omittingEmptySubsequences: false)
 59	            guard parts.count == 2 else {
 60	                throw DockHostConfigurationError.invalidEndpoint(value)
 61	            }
 62	            host = String(parts[0])
 63	            portText = String(parts[1])
 64	        }
 65	
 66	        guard let port = Int(portText) else {
 67	            throw DockHostConfigurationError.invalidPort(portText)
 68	        }
 69	        return try DockRelayEndpoint(host: host, port: port)
 70	    }
