 72	    public static func parseList(_ rawValue: String?) throws -> [DockRelayEndpoint] {
 73	        let endpoints = rawValue?
 74	            .split(separator: ",")
 75	            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
 76	            .filter { !$0.isEmpty } ?? []
 77	        guard !endpoints.isEmpty else {
 78	            throw DockHostConfigurationError.missingEndpoint
 79	        }
 80	
 81	        var seen: Set<String> = []
 82	        return try endpoints.map { value in
 83	            let endpoint = try DockRelayEndpoint.parse(value)
 84	            guard seen.insert(endpoint.id).inserted else {
 85	                throw DockHostConfigurationError.duplicateHostID(endpoint.id)
 86	            }
 87	            return endpoint
 88	        }
 89	    }
