 97	    private static func normalizedHost(_ rawHost: String) throws -> String {
 98	        var host = rawHost.trimmingCharacters(in: .whitespacesAndNewlines)
 99	        if host.hasPrefix("[") && host.hasSuffix("]") {
100	            host.removeFirst()
101	            host.removeLast()
102	        }
103	        while host.hasSuffix(".") {
104	            host.removeLast()
105	        }
106	
107	        guard !host.isEmpty,
108	              !host.contains("://"),
109	              !host.contains("/"),
110	              !host.contains("?"),
111	              !host.contains("#"),
112	              !host.contains("@"),
113	              host.rangeOfCharacter(from: .whitespacesAndNewlines) == nil
114	        else {
115	            throw DockHostConfigurationError.invalidHost(rawHost)
116	        }
117	        return host
118	    }
