121	public enum DockHostDisplayNameResolver {
122	    public static func displayName(for endpoint: DockRelayEndpoint) -> String {
123	        displayName(forHost: endpoint.host)
124	    }
125	
126	    public static func displayName(forHost rawHost: String) -> String {
127	        let host = rawHost.trimmingCharacters(in: .whitespacesAndNewlines)
128	        guard !host.isEmpty, !isIPAddress(host) else {
129	            return host
130	        }
131	
132	        let stripped = strippingKnownSuffixes(from: host)
133	        return stripped
134	            .split(separator: "-")
135	            .map(capitalizedToken)
136	            .joined(separator: "-")
137	    }
138	
139	    private static func strippingKnownSuffixes(from host: String) -> String {
140	        var value = host
141	        for suffix in [".fairy-salmon.ts.net", ".local"] {
142	            if value.lowercased().hasSuffix(suffix) {
143	                value.removeLast(suffix.count)
144	                break
145	            }
146	        }
147	        return value
148	    }
149	
150	    private static func capitalizedToken(_ token: Substring) -> String {
151	        let value = String(token)
152	        guard let first = value.first else {
153	            return value
154	        }
155	        return first.uppercased() + value.dropFirst()
156	    }
157	
158	    private static func isIPAddress(_ host: String) -> Bool {
159	        host.allSatisfy { character in
160	            character.isNumber || character == "." || character == ":"
161	        }
162	    }
163	}
