350	    private func record(hostStates: [DockHostStateViewModel], source: ObservationSource) {
351	        for hostState in hostStates {
352	            let phase: HostConnectivityPhase
353	            switch hostState.status {
354	            case .checking:
355	                phase = .checking
356	            case .loaded(let rowCount):
357	                phase = .online("\(rowCount) sessions")
358	            case .partial(_, let message):
359	                phase = .partial(message)
360	            case .empty:
361	                phase = .online("Online, no sessions")
362	            case .offline(let message):
363	                phase = .offline(message)
364	            case .error(let message):
365	                phase = .error(message)
366	            }
367	            record(host: hostState.host, source: source, phase: phase)
368	        }
369	    }
370	
371	    private func markAllHosts(_ phase: HostConnectivityPhase) {
372	        guard !records.isEmpty else {
373	            overallStatus = rollup([])
374	            return
375	        }
376	        for id in Array(records.keys) {
377	            records[id]?.lifecyclePhase = phase
378	        }
379	        publish()
380	    }
381	
382	    private func clearLifecyclePhase() {
383	        guard !records.isEmpty else {
384	            publishBootstrapStatusIfNeeded()
385	            return
386	        }
387	        for id in Array(records.keys) {
388	            records[id]?.lifecyclePhase = nil
389	        }
