481	    private func rollup(_ hosts: [HostConnectivitySnapshot]) -> AppConnectivityOverallStatus {
482	        guard !hosts.isEmpty else {
483	            return bootstrapStatus ?? .unconfigured("No relay host configured.")
484	        }
485	
486	        if let status = firstStatus(hosts, matching: {
487	            if case .configurationError = $0.phase { return true }
488	            return false
489	        }) {
490	            return .configurationError(status.phase.message)
491	        }
492	        if let status = firstStatus(hosts, matching: {
493	            if case .backgrounded = $0.phase { return true }
494	            return false
495	        }) {
496	            return .backgrounded("\(status.displayName): \(status.phase.message)")
497	        }
498	        if let status = firstStatus(hosts, matching: {
499	            if case .resuming = $0.phase { return true }
500	            return false
501	        }) {
502	            return .resuming("\(status.displayName): \(status.phase.message)")
503	        }
504	        if let status = firstStatus(hosts, matching: {
505	            if case .reconnecting = $0.phase { return true }
506	            return false
507	        }) {
508	            return .reconnecting("\(status.displayName): \(status.phase.message)")
509	        }
510	        if let status = firstStatus(hosts, matching: {
511	            if case .stale = $0.phase { return true }
512	            return false
513	        }) {
514	            return .stale("\(status.displayName): \(status.phase.message)")
515	        }
516	        let onlineLikeCount = hosts.filter { $0.phase.isOnlineLike }.count
517	        let checkingCount = hosts.filter { status in
518	            if case .checking = status.phase {
519	                return true
520	            }
521	            return false
522	        }.count
523	        if checkingCount == hosts.count {
524	            return .checking(hosts.count == 1 ? hosts[0].phase.message : "Checking \(hosts.count) hosts")
525	        }
526	        if onlineLikeCount > 0, checkingCount > 0 {
527	            return .partial("Online \(onlineLikeCount)/\(hosts.count), checking \(checkingCount)")
528	        }
529	        if onlineLikeCount == hosts.count {
530	            if let partial = firstStatus(hosts, matching: {
531	                if case .partial = $0.phase { return true }
532	                return false
533	            }) {
534	                return .partial("\(partial.displayName): \(partial.phase.message)")
535	            }
536	            return .online(hosts.count == 1 ? hosts[0].phase.message : "\(hosts.count) hosts online")
537	        }
538	        if onlineLikeCount > 0 {
539	            let failing = hosts.first { !$0.phase.isOnlineLike } ?? hosts[0]
540	            return .partial("\(failing.displayName): \(failing.phase.message)")
541	        }
542	
543	        if let error = firstStatus(hosts, matching: {
544	            if case .error = $0.phase { return true }
545	            return false
546	        }) {
547	            return .error("\(error.displayName): \(error.phase.message)")
548	        }
549	        if let offline = firstStatus(hosts, matching: {
550	            if case .offline = $0.phase { return true }
551	            return false
552	        }) {
553	            return .offline("\(offline.displayName): \(offline.phase.message)")
554	        }
555	
556	        return .checking("Waiting for first check")
557	    }
