559	    private func priority(for phase: HostConnectivityPhase) -> Int {
560	        switch phase {
561	        case .configurationError:
562	            return 0
563	        case .backgrounded:
564	            return 1
565	        case .resuming:
566	            return 2
567	        case .reconnecting:
568	            return 3
569	        case .stale:
570	            return 4
571	        case .checking:
572	            return 5
573	        case .offline:
574	            return 6
575	        case .error:
576	            return 7
577	        case .partial:
578	            return 8
579	        case .online:
580	            return 9
581	        case .unknown:
582	            return 10
583	        }
584	    }
