 22	function getJSON(url, timeoutMs = HEALTH_TIMEOUT_MS) {
 23	  const client = url.startsWith("https:") ? https : http;
 24	  return new Promise((resolve, reject) => {
 25	    const request = client.get(url, { timeout: timeoutMs }, (response) => {
 26	      const chunks = [];
 27	      response.on("data", (chunk) => chunks.push(chunk));
 28	      response.on("end", () => {
 29	        const body = Buffer.concat(chunks).toString("utf8");
 30	        let parsed = null;
 31	        if (body) {
 32	          try {
 33	            parsed = JSON.parse(body);
 34	          } catch {
 35	            parsed = null;
 36	          }
 37	        }
 38	        resolve({
 39	          statusCode: response.statusCode,
 40	          ok: response.statusCode >= 200 && response.statusCode < 300,
 41	          body: parsed,
 42	        });
 43	      });
 44	    });
 45	    request.on("timeout", () => {
 46	      request.destroy(new Error(`timed out after ${timeoutMs}ms`));
 47	    });
 48	    request.on("error", reject);
 49	  });
 50	}
