324	async function checkRawAppServerHealth(config, tracker) {
325	  const healthURL = rawHealthURLForHistoryURL(config.historyUrl);
326	  try {
327	    const result = await getJSON(healthURL);
328	    tracker.recordRawHealth({
329	      status: result.ok ? "up" : "down",
330	      ok: result.ok,
331	      statusCode: result.statusCode,
332	      url: healthURL,
333	    });
334	  } catch (error) {
335	    tracker.recordRawHealth({
336	      status: "down",
337	      ok: false,
338	      url: healthURL,
339	      error,
340	    });
341	  }
