344	function classifyRelayRequestError(method, error) {
345	  if (error?.code === -32001) {
346	    return {
347	      subsystem: "upstream-overload",
348	      retryable: true,
349	      overload: true,
350	    };
351	  }
352	  if (error?.data?.subsystem) {
353	    return {
354	      ...error.data,
355	      retryable: error.data.retryable ?? error.code !== -32602,
356	    };
357	  }
358	  if (method === "thread/list" || method === "thread/read" || method === "thread/turns/list"
359	    || method === "thread/archive" || method === "thread/unarchive") {
360	    return {
361	      subsystem: "history",
362	      retryable: true,
363	    };
364	  }
365	  if (method === "thread/resume" || method === "turn/start" || method === "turn/steer" || method === "turn/interrupt") {
366	    return {
367	      subsystem: "live-upstream",
368	      retryable: true,
369	    };
370	  }
371	  if (String(method || "").startsWith("audio/transcription/")) {
372	    return {
373	      subsystem: "transcription",
374	      retryable: error?.code !== -32602,
375	    };
376	  }
377	  return undefined;
378	}
