1877	    async fn thread_search_response_inner(
1878	        &self,
1879	        params: ThreadSearchParams,
1880	    ) -> Result<ThreadSearchResponse, JSONRPCErrorError> {
1881	        let ThreadSearchParams {
1882	            cursor,
1883	            limit,
1884	            sort_key,
1885	            sort_direction,
1886	            source_kinds,
1887	            archived,
1888	            search_term,
1889	        } = params;
1890	        let search_term = search_term.trim().to_string();
1891	        let search_term = (!search_term.is_empty())
1892	            .then_some(search_term)
1893	            .ok_or_else(|| invalid_request("thread/search requires a non-empty searchTerm"))?;
1894	        let requested_page_size = limit
1895	            .map(|value| value as usize)
1896	            .unwrap_or(THREAD_LIST_DEFAULT_LIMIT)
1897	            .clamp(1, THREAD_LIST_MAX_LIMIT);
1898	        let store_sort_key = match sort_key.unwrap_or(ThreadSortKey::CreatedAt) {
1899	            ThreadSortKey::CreatedAt => StoreThreadSortKey::CreatedAt,
1900	            ThreadSortKey::UpdatedAt => StoreThreadSortKey::UpdatedAt,
1901	        };
1902	        let store_sort_direction = sort_direction.unwrap_or(SortDirection::Desc);
1903	        let (allowed_sources, source_kind_filter) = compute_source_filters(source_kinds);
1904	        let mut cursor_obj = cursor;
1905	        let mut last_cursor = cursor_obj.clone();
1906	        let mut remaining = requested_page_size;
1907	        let mut search_results = Vec::with_capacity(requested_page_size);
1908	        let mut next_cursor = None;
1909	
1910	        while remaining > 0 {
1911	            let page = self
1912	                .thread_store
1913	                .search_threads(StoreSearchThreadsParams {
1914	                    page_size: remaining.min(THREAD_LIST_MAX_LIMIT),
1915	                    cursor: cursor_obj.clone(),
1916	                    sort_key: store_sort_key,
1917	                    sort_direction: match store_sort_direction {
1918	                        SortDirection::Asc => StoreSortDirection::Asc,
1919	                        SortDirection::Desc => StoreSortDirection::Desc,
1920	                    },
1921	                    allowed_sources: allowed_sources.clone(),
1922	                    archived: archived.unwrap_or(false),
1923	                    search_term: search_term.clone(),
1924	                })
1925	                .await
1926	                .map_err(thread_store_list_error)?;
1927	
1928	            for result in page.items {
1929	                let source = with_thread_spawn_agent_metadata(
1930	                    result.thread.source.clone(),
1931	                    result.thread.agent_nickname.clone(),
1932	                    result.thread.agent_role.clone(),
1933	                );
1934	                if source_kind_filter
1935	                    .as_ref()
1936	                    .is_none_or(|filter| source_kind_matches(&source, filter))
1937	                {
1938	                    search_results.push(result);
1939	                    if search_results.len() >= requested_page_size {
1940	                        break;
1941	                    }
1942	                }
1943	            }
1944	
1945	            remaining = requested_page_size.saturating_sub(search_results.len());
1946	            next_cursor = page.next_cursor;
1947	            if remaining == 0 {
1948	                break;
1949	            }
1950	
1951	            let Some(cursor_val) = next_cursor.clone() else {
1952	                break;
1953	            };
1954	            if last_cursor.as_ref() == Some(&cursor_val) {
1955	                next_cursor = None;
1956	                break;
1957	            }
1958	            last_cursor = Some(cursor_val.clone());
1959	            cursor_obj = Some(cursor_val);
1960	        }
1961	
1962	        let backwards_cursor = search_results.first().and_then(|result| {
1963	            thread_backwards_cursor_for_sort_key(
1964	                &result.thread,
1965	                store_sort_key,
1966	                store_sort_direction,
1967	            )
1968	        });
1969	        let fallback_provider = self.config.model_provider_id.clone();
1970	        let mut results = Vec::with_capacity(search_results.len());
1971	        let mut status_ids = Vec::with_capacity(search_results.len());
1972	        for result in search_results {
1973	            let (thread, _) = thread_from_stored_thread(
1974	                result.thread,
1975	                fallback_provider.as_str(),
1976	                &self.config.cwd,
1977	            );
1978	            status_ids.push(thread.id.clone());
1979	            results.push((thread, result.snippet));
1980	        }
1981	        let statuses = self
1982	            .thread_watch_manager
1983	            .loaded_statuses_for_threads(status_ids)
1984	            .await;
1985	        let data = results
1986	            .into_iter()
1987	            .map(|(mut thread, snippet)| {
1988	                if let Some(status) = statuses.get(&thread.id) {
1989	                    thread.status = status.clone();
1990	                }
1991	                ThreadSearchResult { thread, snippet }
1992	            })
1993	            .collect();
1994	
1995	        Ok(ThreadSearchResponse {
1996	            data,
1997	            next_cursor,
1998	            backwards_cursor,
1999	        })
2000	    }
