307	impl ThreadWatchState {
308	    fn upsert_thread(
309	        &mut self,
310	        thread_id: String,
311	        emit_notification: bool,
312	    ) -> Option<ThreadStatusChangedNotification> {
313	        let previous_status = self.status_for(&thread_id);
314	        let runtime = self
315	            .runtime_by_thread_id
316	            .entry(thread_id.clone())
317	            .or_default();
318	        runtime.is_loaded = true;
319	        self.update_status_watcher_for_thread(&thread_id);
320	        if emit_notification {
321	            self.status_changed_notification(thread_id, previous_status)
322	        } else {
323	            None
324	        }
325	    }
326	
327	    fn remove_thread(&mut self, thread_id: &str) -> Option<ThreadStatusChangedNotification> {
328	        let previous_status = self.status_for(thread_id);
329	        self.runtime_by_thread_id.remove(thread_id);
330	        self.update_status_watcher(thread_id, &ThreadStatus::NotLoaded);
331	        if previous_status.is_some() && previous_status != Some(ThreadStatus::NotLoaded) {
332	            Some(ThreadStatusChangedNotification {
333	                thread_id: thread_id.to_string(),
334	                status: ThreadStatus::NotLoaded,
335	            })
336	        } else {
337	            None
338	        }
339	    }
