341	    fn update_runtime<F>(
342	        &mut self,
343	        thread_id: &str,
344	        mutate: F,
345	    ) -> Option<ThreadStatusChangedNotification>
346	    where
347	        F: FnOnce(&mut RuntimeFacts),
348	    {
349	        let previous_status = self.status_for(thread_id);
350	        let runtime = self
351	            .runtime_by_thread_id
352	            .entry(thread_id.to_string())
353	            .or_default();
354	        runtime.is_loaded = true;
355	        mutate(runtime);
356	        self.update_status_watcher_for_thread(thread_id);
