366	    fn loaded_status_for_thread(&self, thread_id: &str) -> ThreadStatus {
367	        self.status_for(thread_id)
368	            .unwrap_or(ThreadStatus::NotLoaded)
369	    }
370	
371	    fn subscribe(&mut self, thread_id: String) -> watch::Receiver<ThreadStatus> {
372	        let status = self.loaded_status_for_thread(&thread_id);
373	        let sender = self
374	            .status_watcher_by_thread_id
375	            .entry(thread_id)
376	            .or_insert_with(|| watch::channel(status.clone()).0);
377	        sender.subscribe()
378	    }
379	
380	    fn update_status_watcher_for_thread(&mut self, thread_id: &str) {
381	        let status = self.loaded_status_for_thread(thread_id);
382	        self.update_status_watcher(thread_id, &status);
383	    }
384	
385	    fn update_status_watcher(&mut self, thread_id: &str, status: &ThreadStatus) {
386	        let remove_watcher = if let Some(sender) = self.status_watcher_by_thread_id.get(thread_id) {
387	            let status = status.clone();
388	            let _ = sender.send_if_modified(|current| {
389	                if *current == status {
390	                    false
391	                } else {
392	                    *current = status;
393	                    true
394	                }
395	            });
396	            sender.receiver_count() == 0
397	        } else {
398	            false
399	        };
400	        if remove_watcher {
401	            self.status_watcher_by_thread_id.remove(thread_id);
402	        }
403	    }
404	
405	    fn status_changed_notification(
406	        &self,
407	        thread_id: String,
408	        previous_status: Option<ThreadStatus>,
409	    ) -> Option<ThreadStatusChangedNotification> {
410	        let status = self.status_for(&thread_id)?;
411	
412	        if previous_status.as_ref() == Some(&status) {
413	            return None;
414	        }
415	
416	        Some(ThreadStatusChangedNotification { thread_id, status })
417	    }
418	}
