420	#[derive(Clone, Default)]
421	struct RuntimeFacts {
422	    is_loaded: bool,
423	    running: bool,
424	    pending_permission_requests: u32,
425	    pending_user_input_requests: u32,
426	    has_system_error: bool,
427	}
428	
429	fn loaded_thread_status(runtime: &RuntimeFacts) -> ThreadStatus {
430	    if !runtime.is_loaded {
431	        return ThreadStatus::NotLoaded;
432	    }
433	
434	    let mut active_flags = Vec::new();
435	    if runtime.pending_permission_requests > 0 {
436	        active_flags.push(ThreadActiveFlag::WaitingOnApproval);
437	    }
438	    if runtime.pending_user_input_requests > 0 {
439	        active_flags.push(ThreadActiveFlag::WaitingOnUserInput);
440	    }
441	
442	    if runtime.running || !active_flags.is_empty() {
443	        return ThreadStatus::Active { active_flags };
444	    }
445	
446	    if runtime.has_system_error {
447	        return ThreadStatus::SystemError;
448	    }
449	
450	    ThreadStatus::Idle
451	}
